design_text:
{
  "site_summary": "A brutally hot, full-sun, and wind-swept south-facing balcony with low moisture, designed safely for an elderly household cat.",
  "layout_strategy": "The scheme stacks in three distinct layers: trailing Sanvitalia spills over the south railing at the front, upright Rosmarinus and Lantana form a mid-height structural wall at waist level, and low-growing Thymus forms a resilient carpet at the floor level for the cat to safely access.",
  "combination_logic": "The combination contrasts the fine, needle-like foliage of rosemary and thyme with the broader, vibrant daisy-like blooms of Sanvitalia and the rounded clusters of Lantana. Texturally and colorfully, the golden-yellow Sanvitalia and bright Lantana flowers bounce the intense summer sunlight, while the evergreen aromatics provide year-round structural backbone and scent.",
  "zones": [
    {
      "zone_name": "Railing Edge",
      "zone_role": "hanging",
      "layer": "vertical",
      "placement": "On the exterior of the south-facing railing, receiving all-day full sun and maximum wind exposure.",
      "plants": [
        {
          "scientific_name": "Sanvitalia spp.",
          "common_name": "Creeping Zinnia",
          "why": "Thrives in full sun and trails gracefully over the edge of hanging baskets.",
          "role_in_combination": "Contributes bright golden-yellow flower color and a soft, cascading habit that contrasts with the rigid upright plants behind it."
        }
      ],
      "maintenance": [
        "Water daily during peak summer heat due to wind evaporation.",
        "Apply a liquid bloom-booster fertilizer every two weeks in summer.",
        "Trim back leggy stems in mid-summer to encourage a second flush of flowers."
      ]
    },
    {
      "zone_name": "Mid-Level Wall Containers",
      "zone_role": "focal",
      "layer": "mid",
      "placement": "Against the back interior south-facing wall at knee-to-waist height, basking in reflected heat and intense sun.",
      "plants": [
        {
          "scientific_name": "Rosmarinus officinalis",
          "common_name": "Rosemary",
          "why": "Extremely drought-tolerant shrub that loves baked, sunny conditions.",
          "role_in_combination": "Provides architectural height, woody texture, and a strong evergreen vertical element."
        },
        {
          "scientific_name": "Lantana camara",
          "common_name": "Lantana",
          "why": "Loves intense sun and flowers continuously through hot, dry summer months.",
          "role_in_combination": "Adds rich multi-colored floral clusters that contrast sharply with the needle-like foliage of the rosemary."
        }
      ],
      "maintenance": [
        "Water deeply once a week when the top two inches of soil are completely dry.",
        "Prune Rosemary lightly after flowering to maintain shape.",
        "Repot every two years in spring into slightly larger containers with gritty, well-draining soil."
      ]
    },
    {
      "zone_name": "Cat Grazing Pad",
      "zone_role": "grazing",
      "layer": "ground",
      "placement": "On the protected, shaded corner of the balcony floor, easily accessible to the elderly cat.",
      "plants": [
        {
          "scientific_name": "Thymus vulgaris",
          "common_name": "Thyme",
          "why": "A low-growing, tough aromatic herb that tolerates low moisture and light foot or paw traffic.",
          "role_in_combination": "Forms a dense ground-level aromatic carpet that provides textural contrast to the taller shrubs above and a safe nibbling spot for the cat."
        }
      ],
      "maintenance": [
        "Water moderately every 5 to 7 days, avoiding waterlogging.",
        "Clip back lightly after flowering to keep the mat dense and prevent woody stems.",
        "Divide the clump every three years if it spreads too wide for its container."
      ]
    }
  ],
  "care_instructions": [
    {
      "task": "Check soil moisture levels across all containers due to rapid drying from south-facing wind.",
      "frequency": "Daily in summer, twice a week in spring and autumn.",
      "season": "Summer"
    },
    {
      "task": "Feed flowering plants with a balanced, slow-release organic fertilizer.",
      "frequency": "Once a month.",
      "season": "Spring and Summer"
    },
    {
      "task": "Cut back dead growth and check plants for wind or heat stress.",
      "frequency": "Bi-weekly inspection.",
      "season": "Autumn"
    }
  ],
  "care_cautions": [
    "The south-facing wall containers containing Lantana and Rosemary can dry out excessively fast in high summer winds, risking root desiccation if watering is missed.",
    "Lantana foliage can be toxic if ingested in large quantities by pets, so the mid-level wall containers are kept strictly out of the cat's reach.",
    "Sanvitalia in the hanging baskets is vulnerable to wind whip and scorch if allowed to dry out completely under the all-day sun."
  ],
  "pet_safety_note": "The toxic Lantana and woody Rosemary are elevated to mid-level wall containers out of reach, while only cat-safe Thyme is placed at ground level for safe grazing."
}
